const raw = $input.first().json.body || $input.first().json;

// Función para BORRAR todo rastro de etiquetas HTML y sanitizar texto
function stripHTML(text) {
  if (text === undefined || text === null) return "";
  return String(text)
    .replace(/<[^>]*>/g, "")  // Elimina cualquier <tag>
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&")
    .trim();
}

// Mapeo inteligente de severidad a emojis
const sevUpper = String(raw.severidad || raw.severity || raw.nivel || "").toUpperCase();
let emoji = "⚠️";
if (sevUpper.includes("CRITIC") || sevUpper.includes("CRÍT")) emoji = "🚨";
else if (sevUpper.includes("HIGH") || sevUpper.includes("ALTA")) emoji = "🛑";
else if (sevUpper.includes("INFO") || sevUpper.includes("BAJ")) emoji = "ℹ️";
else if (sevUpper.includes("MED")) emoji = "🟡";

// Extracción robusta de campos bilingües y con fallbacks
const severidad = stripHTML(raw.severidad || raw.severity || raw.nivel) || "INFO";
const score = stripHTML(raw.risk_score || raw.score || "N/A");
const evento = stripHTML(raw.tipo_incidente || raw.event_type || raw.evento || "Incidente de Ciberseguridad");
const activo = stripHTML(raw.activo_afectado || raw.affected_asset || raw.recurso) || "Infraestructura Alma";
const control = stripHTML(raw.control_nist || raw.framework_nist || raw.nist_control || raw.nist) || "NIST CSF v2.0";
const ip = stripHTML(raw.responsable_ip || raw.usuario_ip || raw.ip || raw.ip_origen) || "N/A";
const sop = stripHTML(raw.sop_reference || raw.regla || raw.sop);
const detalle = stripHTML(raw.detalles || raw.details || raw.descripcion) || "Sin detalles técnicos adicionales.";
const accion = stripHTML(raw.accion_recomendada || raw.suggested_action || raw.recomendacion) || "Verificar protocolos de seguridad internos.";
const aiSummary = stripHTML(raw.ai_summary || raw.resumen_ia || raw.analisis_ia);
const triageSource = stripHTML(raw.triage_source || raw.triage_origen || raw.ai_provider || "IA");
const id = stripHTML(raw.incident_id || raw.id_incidente) || "N/A";
const timestamp = stripHTML(raw.timestamp || raw.fecha_hora);

// Construcción modular del mensaje
let seccionSop = sop ? `• Procedimiento: ${sop}\n` : "";
let seccionTimestamp = timestamp ? ` | ${timestamp}` : "";
let seccionIa = "";
if (aiSummary && aiSummary !== "N/A" && !aiSummary.includes("Fallback Local")) {
  seccionIa = `\n🧠 TRIAGE ASISTIDO POR IA (${triageSource}):\n${aiSummary}\n`;
}

const mensajeFinal = `
${emoji} [ALERTA DE CIBERSEGURIDAD - SOAR]

• Evento: ${evento}
• Severidad: ${severidad} (Score: ${score}/10)
• Activo: ${activo}
• Control NIST: ${control}
${seccionSop}• IP/Responsable: ${ip}
${seccionIa}
DETALLES TÉCNICOS:
${detalle}

ACCIÓN RECOMENDADA:
${accion}

⏱️ ID: ${id}${seccionTimestamp}
`.trim();

return [{ json: { text: mensajeFinal } }];
